package com.greenocean.backend.community.service;
import com.greenocean.backend.common.exception.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service
public class GroupMemberships {
 private final GroupPolicy p;private final int inviteDays;
 public GroupMemberships(GroupPolicy p,@Value("${greenocean.groups.invitation-days:7}")int days){this.p=p;if(days<1||days>30)throw new IllegalArgumentException("Invitation expiry must be1..30days");inviteDays=days;}
 public void allowed(UUID group,UUID user){p.eligible(user);if(Boolean.TRUE.equals(p.db.queryForObject("SELECT EXISTS(SELECT 1 FROM community_bans WHERE community_id=? AND user_id=? AND(expires_at IS NULL OR expires_at>CURRENT_TIMESTAMP))",Boolean.class,group,user)))GroupPolicy.missing();
  if(Boolean.TRUE.equals(p.db.queryForObject("SELECT EXISTS(SELECT 1 FROM community_members m JOIN blocks b ON (b.blocker_id=m.user_id AND b.blocked_id=?) OR(b.blocker_id=? AND b.blocked_id=m.user_id) WHERE m.community_id=? AND m.role IN('OWNER','MODERATOR'))",Boolean.class,user,user,group)))GroupPolicy.missing();}
 public long rules(UUID group,long version){Long current=p.db.queryForObject("SELECT rules_version FROM communities WHERE id=?",Long.class,group);if(current==null||current!=version)throw new ConflictException("Read and acknowledge the current group rules");return current;}
 public void add(UUID group,UUID user,long version){p.db.update("INSERT INTO community_members(community_id,user_id,rules_version_ack) VALUES(?,?,?) ON CONFLICT(community_id,user_id) DO UPDATE SET rules_version_ack=EXCLUDED.rules_version_ack",group,user,version);}
 @Transactional(readOnly=true) public List<Map<String,Object>> mine(UUID user,int page){return p.db.queryForList("SELECT g.id,g.name,g.slug,g.privacy_type,g.status,g.rules_version,m.role,m.rules_version_ack FROM communities g JOIN community_members m ON m.community_id=g.id WHERE m.user_id=? AND NOT EXISTS(SELECT 1 FROM community_bans b WHERE b.community_id=g.id AND b.user_id=? AND (b.expires_at IS NULL OR b.expires_at>CURRENT_TIMESTAMP)) ORDER BY m.joined_at DESC,g.id DESC LIMIT 20 OFFSET ?",user,user,Math.min(1000,Math.max(0,page))*20);}
 @Transactional(readOnly=true) public List<Map<String,Object>> invitations(UUID group,UUID actor){p.manager(group,actor);return p.db.queryForList("SELECT i.id,i.status,i.expires_at,pr.username,pr.display_name FROM community_invitations i JOIN profiles pr ON pr.user_id=i.target_id WHERE i.community_id=? AND i.status='PENDING' AND i.expires_at>CURRENT_TIMESTAMP ORDER BY i.created_at DESC,i.id DESC LIMIT 20",group);}
 @Transactional(readOnly=true) public List<Map<String,Object>> bans(UUID group,UUID actor){p.manager(group,actor);return p.db.queryForList("SELECT b.user_id,p.username,p.display_name,b.reason,b.expires_at FROM community_bans b JOIN profiles p ON p.user_id=b.user_id WHERE b.community_id=? AND(b.expires_at IS NULL OR b.expires_at>CURRENT_TIMESTAMP) ORDER BY b.created_at DESC,b.user_id LIMIT 100",group);}
 @Transactional(readOnly=true) public List<Map<String,Object>> transfers(UUID actor){return p.db.queryForList("SELECT t.id,t.community_id,c.name,t.expires_at FROM community_ownership_transfers t JOIN communities c ON c.id=t.community_id WHERE t.target_id=? AND t.status='PENDING' AND t.expires_at>CURRENT_TIMESTAMP AND active_group_member(c.id,?) ORDER BY t.created_at DESC,t.id DESC LIMIT 20",actor,actor);}
 @Transactional public void cancelTransfer(UUID group,UUID actor){p.lock(group);p.owner(group,actor);var targets=p.db.queryForList("SELECT target_id FROM community_ownership_transfers WHERE community_id=? AND status='PENDING'",UUID.class,group);p.db.update("UPDATE community_ownership_transfers SET status='CANCELLED' WHERE community_id=? AND status='PENDING'",group);if(!targets.isEmpty()){p.audit(actor,group,"GROUP_TRANSFER_CANCELLED");targets.forEach(p::notify);}}
 @Transactional public void join(UUID group,UUID user,long version){var g=p.lock(group);p.visible(group,user);p.writable(group);allowed(group,user);rules(group,version);p.bound(user,"GROUP_MEMBERSHIP_CHANGE",30);
  if(Boolean.TRUE.equals(p.db.queryForObject("SELECT active_group_member(?,?)",Boolean.class,group,user)))return;
  if("HIDDEN".equals(g.get("privacy_type")))GroupPolicy.missing();
  if("PUBLIC".equals(g.get("privacy_type"))){add(group,user,version);p.notify(user);return;}
  var previous=p.db.queryForList("SELECT status,requested_at,rules_version_ack FROM community_join_requests WHERE community_id=? AND requester_id=?",group,user);
  if(!previous.isEmpty()&&"PENDING".equals(previous.getFirst().get("status"))&&((Number)previous.getFirst().get("rules_version_ack")).longValue()==version)return;
  if(Boolean.TRUE.equals(p.db.queryForObject("SELECT EXISTS(SELECT 1 FROM community_join_requests WHERE community_id=? AND requester_id=? AND status='DECLINED' AND resolved_at>CURRENT_TIMESTAMP-INTERVAL '1 hour')",Boolean.class,group,user)))throw new ConflictException("Please wait before requesting access again");
  p.db.update("INSERT INTO community_join_requests(community_id,requester_id,rules_version_ack) VALUES(?,?,?) ON CONFLICT(community_id,requester_id) DO UPDATE SET status='PENDING',request_version=community_join_requests.request_version+1,rules_version_ack=EXCLUDED.rules_version_ack,requested_at=CURRENT_TIMESTAMP,resolved_at=NULL,resolved_by=NULL",group,user,version);
  p.db.queryForList("SELECT user_id FROM community_members WHERE community_id=? AND role IN('OWNER','MODERATOR') LIMIT 100",UUID.class,group).forEach(p::notify);
 }
 @Transactional public void acknowledge(UUID group,UUID user,long version){p.lock(group);p.member(group,user);rules(group,version);p.db.update("UPDATE community_members SET rules_version_ack=? WHERE community_id=? AND user_id=?",version,group,user);}
 @Transactional public void resolve(UUID group,UUID target,UUID actor,long version,boolean approved){p.lock(group);p.manager(group,actor);p.writable(group);p.bound(actor,"GROUP_REQUEST_REVIEW",60);
  if(approved){allowed(group,target);var current=p.db.queryForList("SELECT rules_version_ack FROM community_join_requests WHERE community_id=? AND requester_id=? AND status='PENDING' AND request_version=?",Long.class,group,target,version);if(current.isEmpty())throw new ConflictException("Request changed or is unavailable");rules(group,current.getFirst());}
  int n=p.db.update("UPDATE community_join_requests SET status=?,resolved_by=?,resolved_at=CURRENT_TIMESTAMP WHERE community_id=? AND requester_id=? AND status='PENDING' AND request_version=?",approved?"APPROVED":"DECLINED",actor,group,target,version);if(n!=1)throw new ConflictException("Request changed or is unavailable");if(approved)add(group,target,p.db.queryForObject("SELECT rules_version FROM communities WHERE id=?",Long.class,group));p.notify(target);p.audit(actor,group,approved?"GROUP_JOIN_APPROVED":"GROUP_JOIN_DECLINED");}
 @Transactional public void cancel(UUID group,UUID user,long version){p.lock(group);p.visible(group,user);if(p.db.update("UPDATE community_join_requests SET status='CANCELLED',resolved_at=CURRENT_TIMESTAMP WHERE community_id=? AND requester_id=? AND status='PENDING' AND request_version=?",group,user,version)!=1)throw new ConflictException("Request changed or is unavailable");}
 @Transactional public void leave(UUID group,UUID user){p.lock(group);var roles=p.db.queryForList("SELECT role FROM community_members WHERE community_id=? AND user_id=?",String.class,group,user);if(roles.isEmpty())GroupPolicy.missing();if("OWNER".equals(roles.getFirst()))throw new ConflictException("Transfer ownership before leaving");p.bound(user,"GROUP_MEMBERSHIP_CHANGE",30);revoke(group,user);p.audit(user,group,"GROUP_LEFT");}
 private void revoke(UUID group,UUID user){p.db.update("DELETE FROM community_event_attendees WHERE user_id=? AND event_id IN(SELECT id FROM community_events WHERE community_id=?)",user,group);p.db.update("DELETE FROM community_members WHERE community_id=? AND user_id=?",group,user);p.db.update("UPDATE community_invitations SET status='REVOKED' WHERE community_id=? AND status='PENDING' AND (target_id=? OR inviter_id=?)",group,user,user);p.db.update("UPDATE community_ownership_transfers SET status='CANCELLED' WHERE community_id=? AND status='PENDING' AND (target_id=? OR from_owner=?)",group,user,user);p.db.update("UPDATE community_join_requests SET status='CANCELLED' WHERE community_id=? AND requester_id=? AND status='PENDING'",group,user);}
 @Transactional public void remove(UUID group,UUID target,UUID actor,String action,String reason,java.time.Instant until){p.lock(group);String role=p.manager(group,actor);p.writable(group);String targetRole=p.member(group,target);if("OWNER".equals(targetRole)||("MODERATOR".equals(targetRole)&&!"OWNER".equals(role))||actor.equals(target))throw new ForbiddenException("This role cannot be removed or restricted by you");p.bound(actor,"GROUP_MEMBER_ACTION",30);
  if("RESTRICT".equals(action)){if(until==null||!until.isAfter(java.time.Instant.now()))throw new IllegalArgumentException("Provide a future restriction expiry");p.db.update("UPDATE community_members SET restricted_until=? WHERE community_id=? AND user_id=?",java.time.OffsetDateTime.ofInstant(until,java.time.ZoneOffset.UTC),group,target);}
  else{if(!Set.of("REMOVE","BAN").contains(action))throw new IllegalArgumentException("Invalid member action");revoke(group,target);if("BAN".equals(action))p.db.update("INSERT INTO community_bans(community_id,user_id,actor_id,reason,expires_at) VALUES(?,?,?,?,?) ON CONFLICT(community_id,user_id) DO UPDATE SET actor_id=EXCLUDED.actor_id,reason=EXCLUDED.reason,expires_at=EXCLUDED.expires_at",group,target,actor,reason,until==null?null:java.time.OffsetDateTime.ofInstant(until,java.time.ZoneOffset.UTC));}
  p.db.update("INSERT INTO community_member_actions(community_id,user_id,actor_id,action,reason,expires_at) VALUES(?,?,?,?,?,?)",group,target,actor,action,reason,until==null?null:java.time.OffsetDateTime.ofInstant(until,java.time.ZoneOffset.UTC));
  p.audit(actor,group,"GROUP_MEMBER_"+action);p.notify(target);
 }
 @Transactional public void unban(UUID group,UUID target,UUID actor){p.lock(group);p.owner(group,actor);p.writable(group);p.bound(actor,"GROUP_MEMBER_ACTION",30);p.db.update("DELETE FROM community_bans WHERE community_id=? AND user_id=?",group,target);p.db.update("INSERT INTO community_member_actions(community_id,user_id,actor_id,action,reason) VALUES(?,?,?,'UNBAN','Group ban lifted by owner')",group,target,actor);p.audit(actor,group,"GROUP_UNBAN");}
 @Transactional public Map<String,Object> invite(UUID group,UUID actor,UUID target,UUID retry){var g=p.lock(group);p.manager(group,actor);p.writable(group);allowed(group,target);if(actor.equals(target))throw new IllegalArgumentException("Choose another eligible account");
  var prior=p.db.queryForList("SELECT id,community_id,target_id,status,expires_at FROM community_invitations WHERE inviter_id=? AND retry_key=?",actor,retry);if(!prior.isEmpty()){if(!group.equals(prior.getFirst().get("community_id"))||!target.equals(prior.getFirst().get("target_id")))throw new ConflictException("Retry key belongs to a different invitation");return prior.getFirst();}
  p.db.update("UPDATE community_invitations SET status='EXPIRED' WHERE community_id=? AND status='PENDING' AND expires_at<=CURRENT_TIMESTAMP",group);if(p.db.queryForObject("SELECT count(*) FROM community_invitations WHERE community_id=? AND status='PENDING'",Integer.class,group)>=20)throw new ConflictException("Resolve existing invitations first");p.bound(actor,"GROUP_INVITE",30);
  UUID id=UUID.randomUUID();try{p.db.update("INSERT INTO community_invitations(id,community_id,inviter_id,target_id,retry_key,expires_at) VALUES(?,?,?,?,?,CURRENT_TIMESTAMP+(? * INTERVAL '1 day'))",id,group,actor,target,retry,inviteDays);}catch(org.springframework.dao.DuplicateKeyException duplicate){throw new ConflictException("An invitation is already pending");}p.notify(target);return Map.of("id",id,"status","PENDING");}
 @Transactional(readOnly=true) public List<Map<String,Object>> inbox(UUID user){return p.db.queryForList("SELECT i.id,c.name,c.privacy_type,c.rules_version,(SELECT jsonb_agg(rule_text ORDER BY position)::text FROM community_rules WHERE community_id=c.id) AS rules FROM community_invitations i JOIN communities c ON c.id=i.community_id WHERE i.target_id=? AND i.status='PENDING' AND i.expires_at>CURRENT_TIMESTAMP AND c.status='ACTIVE' AND EXISTS(SELECT 1 FROM community_members m JOIN users u ON u.id=m.user_id WHERE m.community_id=c.id AND m.user_id=i.inviter_id AND m.role IN('OWNER','MODERATOR') AND u.status='ACTIVE') AND NOT EXISTS(SELECT 1 FROM blocks b WHERE(b.blocker_id=i.inviter_id AND b.blocked_id=i.target_id) OR(b.blocker_id=i.target_id AND b.blocked_id=i.inviter_id)) AND NOT EXISTS(SELECT 1 FROM community_bans b WHERE b.community_id=c.id AND b.user_id=i.target_id AND(b.expires_at IS NULL OR b.expires_at>CURRENT_TIMESTAMP)) ORDER BY i.created_at DESC,i.id DESC LIMIT 50",user);}
 @Transactional public UUID invitation(UUID id,UUID actor,String action,long version){var first=p.db.queryForList("SELECT community_id FROM community_invitations i WHERE id=? AND (target_id=? OR inviter_id=? OR EXISTS(SELECT 1 FROM community_members m WHERE m.community_id=i.community_id AND m.user_id=? AND m.role IN('OWNER','MODERATOR')))",id,actor,actor,actor);if(first.isEmpty())GroupPolicy.missing();UUID group=(UUID)first.getFirst().get("community_id");p.lock(group);var i=p.db.queryForMap("SELECT * FROM community_invitations WHERE id=? FOR UPDATE",id);
  if("REVOKE".equals(action)){p.manager(group,actor);if("REVOKED".equals(i.get("status")))return group;if(!"PENDING".equals(i.get("status")))throw new ConflictException("Invitation already resolved; use member management if needed");p.db.update("UPDATE community_invitations SET status='REVOKED' WHERE id=? AND status='PENDING'",id);return group;}
  if(!actor.equals(i.get("target_id")))GroupPolicy.missing();p.writable(group);allowed(group,actor);
  if("ACCEPTED".equals(i.get("status"))&&"ACCEPT".equals(action)&&Boolean.TRUE.equals(p.db.queryForObject("SELECT active_group_member(?,?)",Boolean.class,group,actor)))return group;
  if(!"PENDING".equals(i.get("status"))||!instant(i.get("expires_at")).isAfter(java.time.Instant.now()))GroupPolicy.missing();p.manager(group,(UUID)i.get("inviter_id"));
  if(!Set.of("ACCEPT","DECLINE").contains(action))throw new IllegalArgumentException("Invalid invitation action");if("ACCEPT".equals(action)){rules(group,version);add(group,actor,version);}p.db.update("UPDATE community_invitations SET status=? WHERE id=?","ACCEPT".equals(action)?"ACCEPTED":"DECLINED",id);p.notify((UUID)i.get("inviter_id"));p.audit(actor,group,"GROUP_INVITATION_"+action);return group;
 }
 @Transactional public UUID transfer(UUID group,UUID actor,UUID target){p.lock(group);p.owner(group,actor);p.writable(group);allowed(group,target);p.member(group,target);if(actor.equals(target)||p.db.queryForObject("SELECT count(*) FROM community_members WHERE community_id=? AND role='OWNER'",Integer.class,group)!=1)throw new ConflictException("Ownership requires an independent eligible member and one current owner");p.bound(actor,"GROUP_TRANSFER",10);p.db.update("UPDATE community_ownership_transfers SET status='EXPIRED' WHERE community_id=? AND status='PENDING' AND expires_at<=CURRENT_TIMESTAMP",group);var pending=p.db.queryForList("SELECT id,target_id FROM community_ownership_transfers WHERE community_id=? AND status='PENDING'",group);if(!pending.isEmpty()){if(target.equals(pending.getFirst().get("target_id")))return (UUID)pending.getFirst().get("id");throw new ConflictException("Cancel the pending transfer before choosing another member");}UUID id=UUID.randomUUID();p.db.update("INSERT INTO community_ownership_transfers(id,community_id,from_owner,target_id) VALUES(?,?,?,?)",id,group,actor,target);p.notify(target);p.audit(actor,group,"GROUP_TRANSFER_REQUESTED");return id;}
 @Transactional public void acceptTransfer(UUID id,UUID actor,boolean accepted){var rows=p.db.queryForList("SELECT community_id FROM community_ownership_transfers WHERE id=? AND target_id=?",id,actor);if(rows.isEmpty())GroupPolicy.missing();UUID group=(UUID)rows.getFirst().get("community_id");p.lock(group);var t=p.db.queryForMap("SELECT * FROM community_ownership_transfers WHERE id=? FOR UPDATE",id);if(!"PENDING".equals(t.get("status"))||!instant(t.get("expires_at")).isAfter(java.time.Instant.now()))throw new ConflictException("Transfer is unavailable");p.writable(group);allowed(group,actor);p.member(group,actor);p.owner(group,(UUID)t.get("from_owner"));if(accepted){p.db.update("UPDATE community_members SET role='MODERATOR' WHERE community_id=? AND user_id=?",group,t.get("from_owner"));p.db.update("UPDATE community_members SET role='OWNER' WHERE community_id=? AND user_id=?",group,actor);}p.db.update("UPDATE community_ownership_transfers SET status=? WHERE id=?",accepted?"ACCEPTED":"DECLINED",id);p.audit(actor,group,"GROUP_TRANSFER_"+(accepted?"ACCEPTED":"DECLINED"));}
 private java.time.Instant instant(Object timestamp){if(timestamp instanceof java.sql.Timestamp t)return t.toInstant();if(timestamp instanceof java.time.OffsetDateTime t)return t.toInstant();throw new ConflictException("Stored expiry is unavailable");}

}
